class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        java.util.TreeMap<Integer, Integer> lo = new java.util.TreeMap<>(java.util.Collections.reverseOrder());
        java.util.TreeMap<Integer, Integer> hi = new java.util.TreeMap<>();
        int loSize = 0, hiSize = 0;
        double[] result = new double[nums.length - k + 1];
        for (int i = 0; i < nums.length; i++) {
            if (loSize == 0 || nums[i] <= lo.firstKey()) { add(lo, nums[i]); loSize++; }
            else { add(hi, nums[i]); hiSize++; }
            while (loSize > hiSize + 1) { int v = lo.firstKey(); remove(lo, v); add(hi, v); loSize--; hiSize++; }
            while (hiSize > loSize) { int v = hi.firstKey(); remove(hi, v); add(lo, v); hiSize--; loSize++; }
            if (i >= k - 1) {
                if (k % 2 == 1) result[i - k + 1] = lo.firstKey();
                else result[i - k + 1] = ((long) lo.firstKey() + hi.firstKey()) / 2.0;
                int out = nums[i - k + 1];
                if (out <= lo.firstKey()) { remove(lo, out); loSize--; }
                else { remove(hi, out); hiSize--; }
                while (loSize > hiSize + 1) { int v = lo.firstKey(); remove(lo, v); add(hi, v); loSize--; hiSize++; }
                while (hiSize > loSize) { int v = hi.firstKey(); remove(hi, v); add(lo, v); hiSize--; loSize++; }
            }
        }
        return result;
    }
    private void add(java.util.TreeMap<Integer, Integer> map, int val) { map.merge(val, 1, Integer::sum); }
    private void remove(java.util.TreeMap<Integer, Integer> map, int val) {
        int cnt = map.get(val);
        if (cnt == 1) map.remove(val); else map.put(val, cnt - 1);
    }
}
